from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE
import io

prs = Presentation("input.pptx")

excel_blob = None
update_text = None

for i, slide in enumerate(prs.slides):
    print(f"--- Slide {i+1} ---")
    for shape in slide.shapes:
        try:
            print(f"Shape ID: {shape.shape_id}, Name: {shape.name}, Type: {shape.shape_type}")
            if shape.has_text_frame:
                text = shape.text_frame.text
                print(f"  Text: {text}")
                if "Update:" in text or "Rate" in text or "Exchange" in text:
                     update_text = text

            if shape.shape_type == MSO_SHAPE_TYPE.EMBEDDED_OLE_OBJECT:
                print(f"  Found OLE Object: {shape.name}")
                # Try to access ole_format
                try:
                    ole = shape.ole_format
                    print(f"  OLE Class Type: {ole.prog_id}")
                    excel_blob = ole.blob
                    print(f"  Blob size: {len(excel_blob)} bytes")
                except Exception as e:
                    print(f"  Could not access OLE details: {e}")

        except Exception as e:
            print(f"Error processing shape: {e}")

if update_text:
    print(f"\nFOUND UPDATE TEXT: {update_text}")
if excel_blob:
    print(f"FOUND EXCEL BLOB")
